export function Header({ userInitials = 'AK' }) {
  return (
    <header className="flex items-center justify-between pb-6">
      <input
        type="text"
        placeholder="Search projects and tasks..."
        className="bg-slate-200/60 text-sm rounded-lg px-3 py-2 w-80 text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500"
