export function MetricCard({ title, value, subtext }: { title: string; value: string | number; subtext: string }) {
  return (
    <div className="bg-white p-5 rounded-xl border border-slate-100 shadow-sm flex flex-col justify-between">
      <span className="text-xs text-slate-500 font-medium">{title}</span>
      <div className="text-3xl font-bold text-slate-900 my-2">{value}</div>
      <span className="text-xs font-medium text-emerald-600">{subtext}</span>
    </div>
  );
}

export function StatusBadge({ status }: { status: 'On track' | 'At risk' | 'Blocked' }) {
  const styles = {
    'On track': 'bg-emerald-50 text-emerald-600 border border-emerald-200',
    'At risk': 'bg-amber-50 text-amber-600 border border-amber-200',
    'Blocked': 'bg-rose-50 text-rose-600 border border-rose-200'
  };
  return (
    <span className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${styles[status]}`}>
      {status}
    </span>
  );
}

